import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SubscribeScreenProps = Record<string, any>;

const SubscribeScreen: React.FC<SubscribeScreenProps> = ({
  backgroundColor = "#101722",
  transparentBackground = false,
  durationInSeconds = 4,
  iconColor = "#B87333",
  mainTextColor = "#B87333",
  subTextColor = "#FFFDD0",
  mainText = "SUBSCRIBE",
  subText = "New video drops Monday.",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const s = Math.min(width, height);

  // --- Animation Timing & Physics ---
  
  // 1. Bell Entrance & Wobble
  const bellScale = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 150 },
  });

  const bellRotation = interpolate(
    frame,
    [15, 18, 21, 24, 27, 30, 33],
    [0, -25, 20, -15, 10, -5, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 2. Main Text Snap In
  const mainTextScale = spring({
    frame: frame - 10,
    fps,
    config: { damping: 9, stiffness: 180 },
  });

  // 3. Subtext Fade & Slide
  const subTextOpacity = interpolate(frame, [25, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const subTextY = interpolate(frame, [25, 35], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. Exit Animation (Bell fades, text holds)
  const exitStartFrame = Math.max(0, durationInSeconds * fps - 15);
  const bellOpacity = interpolate(
    frame,
    [exitStartFrame, exitStartFrame + 10],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Bell Icon Container */}
      <div
        style={{
          transform: `scale(${bellScale})`,
          opacity: bellOpacity,
          marginBottom: height * 0.03,
          transition: "none",
        }}
      >
        <div
          style={{
            transform: `rotate(${bellRotation}deg)`,
            transformOrigin: "50% 15%", // Pivot from top center (handle) for realistic ringing
            transition: "none",
          }}
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill={iconColor}
            width={s * 0.15}
            height={s * 0.15}
            style={{ transition: "none" }}
          >
            <path d="M12 22c1.1 0 2-.9 2-2h-4c0 1.1.9 2 2 2zm6-6v-5c0-3.07-1.63-5.64-4.5-6.32V4c0-.83-.67-1.5-1.5-1.5s-1.5.67-1.5 1.5v.68C7.64 5.36 6 7.92 6 11v5l-2 2v1h16v-1l-2-2z" />
          </svg>
        </div>
      </div>

      {/* Main Text Container */}
      <div
        style={{
          transform: `scale(${mainTextScale})`,
          transition: "none",
          marginBottom: height * 0.02,
        }}
      >
        <h1
          style={{
            fontWeight: 700,
            fontSize: s * 0.08,
            color: mainTextColor,
            margin: 0,
            lineHeight: 1,
            letterSpacing: "0.02em",
            transition: "none",
          }}
        >
          {mainText}
        </h1>
      </div>

      {/* Subtext Container */}
      <div
        style={{
          opacity: subTextOpacity,
          transform: `translateY(${subTextY}px)`,
          transition: "none",
        }}
      >
        <p
          style={{
            fontWeight: 400,
            fontSize: s * 0.03,
            color: subTextColor,
            margin: 0,
            transition: "none",
          }}
        >
          {subText}
        </p>
      </div>
    </AbsoluteFill>
  );
};

export default SubscribeScreen;